proposedCaseSchema:
// ---------------------------------------------------------------------------
// src/features/placements/data/case-studies.ts
// Reuses every primitive from case-primitives.ts — critically CalcLine, so a
// single arithmetic test covers guesstimates and cases alike.
// ---------------------------------------------------------------------------

import type {
  CalcLine,
  Difficulty,
  Probe,
  TreeNode,
} from "./case-primitives";

export type CaseFamily =
  | "Profitability"
  | "Market entry"
  | "Pricing"
  | "Growth"
  | "M&A / Due diligence"
  | "Operations"
  | "Public policy"
  | "Unconventional";

export type ExhibitKind =
  | "table"            // plain rows and columns
  | "bridge"           // a walk from one figure to another
  | "segment-split"    // shares of a whole, by segment
  | "timeseries"       // periods across columns
  | "option-compare"   // two or more mutually exclusive options
  | "matrix";          // items as columns, metrics as rows

export interface CaseExhibit {
  id: string;
  /** Display label, e.g. "Exhibit 2". */
  number: string;
  title: string;
  kind: ExhibitKind;
  /** What the interviewer says while handing it over. */
  handoffLine: string;
  columns: readonly string[];
  /** Row-major. First cell of each row is the row header. */
  rows: readonly (readonly string[])[];
  /** Units, definitions, and the caveats a careful reader would want. */
  footnotes?: readonly string[];
  /**
   * The single observation a strong candidate makes within ~30 seconds.
   * This is the skill being trained; everything else is decoration.
   */
  headlineRead: string;
  /** The deliberate omission the candidate must notice and ask for. */
  whatItDoesNotTell: string;
  /**
   * Release gate for partner practice: what the candidate must have
   * articulated before this exhibit is earned.
   */
  unlockCondition: string;
  /** Metrics the candidate is expected to derive, not read off. */
  derivedMetricsExpected?: readonly string[];
}

/** One quantitative beat inside a case. */
export interface CaseQuantStep {
  id: string;
  /** The question the interviewer poses, or the candidate should pose. */
  question: string;
  /** Machine-checkable arithmetic — identical primitive to guesstimates. */
  lines: readonly CalcLine[];
  /** The "so what". A number without this is an incomplete answer. */
  insight: string;
  /** The specific miscalculation most candidates make here. */
  commonError?: string;
  /** Exhibit ids this step draws on. */
  usesExhibits?: readonly string[];
}

/** The mid-case fact that invalidates a committed plan. */
export interface CaseTwist {
  /** When the interviewer drops it. */
  trigger: string;
  newFact: string;
  whyItBreaksThePlan: string;
  /**
   * The house answer shape: name the dilemma, Option A pros/cons against
   * Option B, land on a hybrid with a reason. Never defend the old plan.
   */
  expectedResponse: string;
  /** What a candidate who digs in instead sounds like. */
  failureMode: string;
}

export type RubricDimension =
  | "Structure"
  | "Quantitative rigour"
  | "Business judgement"
  | "Communication"
  | "Synthesis";

export interface RubricRow {
  dimension: RubricDimension;
  /** Weights across all rows must sum to 100. Asserted by test. */
  weight: number;
  strong: string;
  adequate: string;
  weak: string;
}

export interface CaseRecommendation {
  /** May be — and often should be — a conditional yes. */
  verdict: string;
  /** The number or named condition the verdict hangs on. */
  conditionalOn?: string;
  shortTerm: readonly string[];
  longTerm: readonly string[];
  /** Every risk carries its own mitigation. Never a bare list. */
  risks: readonly { risk: string; mitigation: string }[];
  /** Must not contradict the verdict — reviewed on author. */
  whatWouldMakeYouWalkAway?: readonly string[];
}

export interface CaseStudy {
  id: string;
  number: string;
  title: string;
  family: CaseFamily;
  /** The casebook archetype this case drills. */
  archetype: string;
  difficulty: Difficulty;
  estimatedMinutes: number;

  company: {
    name: string;
    sector: string;
    /** Always true. Enforced by the type, not by convention. */
    fictional: true;
    oneLine: string;
  };

  /** Read aloud verbatim. Deliberately omits the objective. */
  prompt: string;
  /** The objective the candidate must extract by asking. Not in the prompt. */
  hiddenObjective: string;

  clarifiers: readonly {
    question: string;
    whyItMatters: string;
    /** What the interviewer actually replies — terse, volunteering nothing. */
    interviewerAnswer: string;
    /** True for the four near-mandatory openers. */
    isMandatory?: boolean;
  }[];

  /** Released one at a time, only when the exact metric is named. */
  dataOnRequest: readonly {
    askedFor: string;
    answer: string;
    /** Set when the ask is a trap, e.g. sunk R&D cost. */
    isRedHerring?: boolean;
  }[];

  /** Expected issue tree, values on nodes — the tree is a ledger. */
  structure: TreeNode;
  /** How to say the structure aloud in ~90 seconds, then ask to proceed. */
  structureNarration: string;
  /** Branches a strong candidate prunes with a reason, before being told. */
  branchesToPrune: readonly { branch: string; whyRuledOut: string }[];

  exhibits: readonly CaseExhibit[];
  quantWalkthrough: readonly CaseQuantStep[];
  twist?: CaseTwist;

  rootCause: string;
  /** Plausible causes a candidate will chase, and how each is eliminated. */
  rejectedHypotheses: readonly { hypothesis: string; howEliminated: string }[];

  recommendation: CaseRecommendation;

  /** Post-analysis probes. Same primitive as guesstimates. */
  probes: readonly Probe[];
  rubric: readonly RubricRow[];
  /** What separates strong from average. The casebooks' highest-value page. */
  browniePoints: readonly string[];
  /** The transferable principle, independent of this company. */
  keyLearnings: readonly string[];

  relatedGuesstimateIds?: readonly string[];
  relatedFrameworkIds?: readonly string[];
}

export const caseStudies: readonly CaseStudy[] = [/* … */];

proposedGuesstimateSchema:
// ---------------------------------------------------------------------------
// src/features/placements/data/case-primitives.ts
// Shared by guesstimates, cases and frameworks so one test suite covers all.
// ---------------------------------------------------------------------------

export type Difficulty = "Easy" | "Medium" | "Hard";

export type Route = "Top-down" | "Bottom-up" | "Hybrid" | "Probabilistic";

/** How much weight a number can bear when an interviewer pushes on it. */
export type Confidence = "anchor" | "defensible" | "judgement" | "shaky";

/** Where the number came from — the answer to "why that number?" */
export type AssumptionBasis =
  | "census-anchor"        // national or city demographic constant
  | "published-benchmark"  // an industry or regulator figure you could cite
  | "physical-constant"    // hours in a day, seats in a coach, litres in a tank
  | "observed-behaviour"   // what you can see on a street or a campus
  | "structural-logic"     // forced by an identity or a constraint, not observed
  | "declared-judgement";  // openly a guess, and said to be one

export interface Assumption {
  /** Stable id. Referenced by CalcLine.uses and Sensitivity.assumptionId. */
  id: string;
  /** The lever being assumed, e.g. "Urban share of population". */
  lever: string;
  /** Display form, may carry units: "35%", "₹20 / litre". */
  value: string;
  /** Machine form where one exists: 0.35, 20. */
  numeric?: number;
  unit?: string;
  basis: AssumptionBasis;
  /** One sentence to say out loud when challenged on this number. */
  defence: string;
  confidence: Confidence;
  /** A reasonable alternative an interviewer may prefer, and its effect. */
  contestedBy?: string;
  /** Id into the shared constants registry, when it is a standard anchor. */
  constantId?: string;
}

/**
 * One arithmetic step.
 *
 * `expr` MUST contain only digits, decimal points, + - * / ( ) and
 * whitespace — no identifiers, no units, no thousands separators — so a
 * build-time test can evaluate it and assert it equals `result`.
 */
export interface CalcLine {
  id: string;
  /** Plain-language name of what this line produces. */
  label: string;
  /** Machine-evaluable, e.g. "1400000000 * 0.35 * 0.6". */
  expr: string;
  /** Human-readable, e.g. "1,400 Mn × 35% urban × 60% adult". */
  display: string;
  /** The value `expr` must evaluate to. Asserted in CI. */
  result: number;
  /** Allowed relative error where display rounding compounds. Default 0. */
  tolerance?: number;
  unit: string;
  /** The rounded figure actually carried forward, if different: "≈ 290 Mn". */
  carriedForward?: string;
  /** Assumption ids consumed. Every id must exist in `assumptions`. */
  uses: readonly string[];
  /** Why this intermediate matters. Enforces the "so what" rule. */
  soWhat?: string;
}

/** Recursive so a 4-5 level funnel can be represented, with values on nodes. */
export interface TreeNode {
  label: string;
  formula?: string;
  /** The absolute figure at this node — the tree doubles as a ledger. */
  value?: string;
  note?: string;
  /** Set on the branch that carries the answer, for visual emphasis. */
  isCriticalPath?: boolean;
  children?: readonly TreeNode[];
}

export interface Scope {
  /** One sentence: exactly what is being counted. */
  countingWhat: string;
  unit: string;
  /** Stock vs flow, made explicit. The first-order scope error. */
  timeBasis:
    | "stock (point in time)"
    | "flow (per day)"
    | "flow (per week)"
    | "flow (per year)";
  geography: string;
  /** Boundaries to name BEFORE computing. */
  included: readonly string[];
  excluded: readonly string[];
  /** The specific ambiguity this question is built around. */
  boundaryTrap: string;
}

export interface RouteChoice {
  chosen: Route;
  /** Why this route, in the candidate's own voice. */
  why: string;
  /** The route not taken, and why it is weaker *here*. */
  rejected: { route: Route; whyNot: string };
}

export interface Triangulation {
  label: string;              // "Supply-side cross-check"
  route: Route;
  premise: string;
  /** Fully worked and machine-checked, like the primary route. */
  lines: readonly CalcLine[];
  answer: string;
  /** The gap vs the primary answer, and what the gap tells you. */
  verdict: string;
}

export interface SensitivityCase {
  scenario: "Conservative" | "Base" | "Aggressive";
  leverValue: string;
  answer: string;
  /** Signed change vs base, e.g. "−38%". */
  deltaVsBase: string;
}

export interface Sensitivity {
  /** Must match an id in `assumptions`. Asserted by test. */
  assumptionId: string;
  /** Why this lever is the one that moves the answer. */
  whyThisLever: string;
  cases: readonly SensitivityCase[];
  /** What would have to be true to flip the conclusion. */
  breakpoint: string;
  /** What to say when there is no time to run the grid. */
  oneLiner: string;
}

export interface Trap {
  trap: string;
  /** The mechanism, not just the warning. */
  whyItHappens: string;
  fix: string;
}

export interface Probe {
  /** What the interviewer actually asks. */
  question: string;
  /** What is being tested. */
  intent: string;
  goodAnswer: string;
  /** The plausible-sounding non-answer most candidates give. */
  weakAnswer?: string;
}

// ---------------------------------------------------------------------------
// src/features/placements/data/guesstimates.ts
// ---------------------------------------------------------------------------

export type GuesstimateArchetype =
  | "population-funnel"
  | "household-ownership-stock"
  | "installed-base-replacement"
  | "capacity-bottleneck"
  | "single-asset-revenue"
  | "network-price-mix"
  | "penetration-cascade"
  | "unit-chain-infrastructure"
  | "physical-proxy-consumable"
  | "funnel-conversion-fmcg"
  | "revenue-pool-take-rate"
  | "closed-population"
  | "occupational-cohort"
  | "expected-value";

export interface Guesstimate {
  id: string;
  number: string;
  question: string;
  /** ~8 words, for tab and card labels. */
  shortLabel: string;
  archetype: GuesstimateArchetype;
  difficulty: Difficulty;
  estimatedMinutes: number;
  /** The one transferable idea this question exists to teach. */
  teachingPoint: string;

  scope: Scope;
  route: RouteChoice;
  /** Recursive, values on every node. */
  tree: TreeNode;
  assumptions: readonly Assumption[];
  /** Ordered. The last line must equal `answer.numeric`. */
  calculation: readonly CalcLine[];

  answer: {
    headline: string;
    numeric: number;
    unit: string;
    /** An honest band, not false precision. */
    band: string;
    /** e.g. "10^5" — being right to the power of ten is the real test. */
    orderOfMagnitude: string;
  };

  /** An independent second route, fully worked. Required, not optional. */
  triangulation: Triangulation;
  sensitivity: Sensitivity;
  /** Plausibility tests, not arithmetic re-checks. */
  sanityChecks: readonly string[];
  traps: readonly Trap[];
  probes: readonly Probe[];
  /** Ids into the shared constants registry. */
  constantsUsed: readonly string[];
  relatedCaseIds?: readonly string[];
}

export const guesstimates: readonly Guesstimate[] = [/* … */];
